export type Period = "7d" | "30d" | "90d";

export const periodDays: Record<Period, number> = {
  "7d": 7,
  "30d": 30,
  "90d": 90,
};

export const periodLabels: Record<Period, string> = {
  "7d": "7 days",
  "30d": "30 days",
  "90d": "90 days",
};

export interface Metric {
  id: string;
  label: string;
  summary: "last" | "mean";
  format: Intl.NumberFormatOptions;
  invert?: boolean;
  points?: boolean;
  values: number[];
}

const dayMs = 86_400_000;
const historyDays = 180;
const lastDay = Date.UTC(2026, 8, 30);

function random(seed: number) {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let value = Math.imul(state ^ (state >>> 15), 1 | state);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4_294_967_296;
  };
}

function series(
  seed: number,
  point: (index: number, weekday: number, noise: number) => number,
) {
  const next = random(seed);
  return Array.from({ length: historyDays }, (_, index) => {
    const weekday = new Date(dayStart(index)).getUTCDay();
    return point(index, weekday, next() * 2 - 1);
  });
}

function dayStart(index: number) {
  return lastDay - (historyDays - 1 - index) * dayMs;
}

const mrr = (() => {
  let value = 61_840;
  return series(11, (index, weekday, noise) => {
    if (index > 0) {
      const working = weekday !== 0 && weekday !== 6;
      value += (working ? 92 : 28) + noise * 70 - (index === 131 ? 640 : 0);
    }
    return Math.round(value);
  });
})();

const activeUsers = series(23, (index, weekday, noise) => {
  const weekend = weekday === 0 || weekday === 6 ? 0.71 : 1;
  const trend = 2_180 + index * 2.6;
  return Math.round(trend * weekend * (1 + noise * 0.035));
});

const churn = series(37, (index, _weekday, noise) => {
  const trend = 0.0292 - index * 0.000_026;
  const bump = index > 128 && index < 146 ? 0.0021 : 0;
  return Math.round((trend + bump + noise * 0.000_12) * 10_000) / 10_000;
});

const latency = series(41, (index, weekday, noise) => {
  const weekend = weekday === 0 || weekday === 6 ? -14 : 0;
  const incident = index === 158 ? 96 : index === 159 ? 41 : 0;
  return Math.round(231 - index * 0.21 + weekend + incident + noise * 9);
});

export const metrics: Metric[] = [
  {
    id: "mrr",
    label: "Monthly recurring revenue",
    summary: "last",
    format: { style: "currency", currency: "USD", maximumFractionDigits: 0 },
    values: mrr,
  },
  {
    id: "dau",
    label: "Daily active users",
    summary: "mean",
    format: { maximumFractionDigits: 0 },
    values: activeUsers,
  },
  {
    id: "churn",
    label: "Churn rate, 30-day",
    summary: "last",
    format: {
      style: "percent",
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    },
    invert: true,
    points: true,
    values: churn,
  },
  {
    id: "latency",
    label: "p95 response time",
    summary: "mean",
    format: { style: "unit", unit: "millisecond", maximumFractionDigits: 0 },
    invert: true,
    values: latency,
  },
];

const dayFormat = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  timeZone: "UTC",
});

function summarize(metric: Metric, values: number[]) {
  if (metric.summary === "last") return values[values.length - 1];
  const mean =
    values.reduce((total, value) => total + value, 0) / values.length;
  return Math.round(mean);
}

export function readMetric(metric: Metric, period: Period) {
  const days = periodDays[period];
  const current = metric.values.slice(-days);
  const previous = metric.values.slice(-days * 2, -days);
  const value = summarize(metric, current);
  const before = summarize(metric, previous);
  const change = metric.points
    ? Math.round((value - before) * 10_000) / 100
    : Math.round(((value - before) / before) * 1_000) / 10;
  const start = historyDays - days;
  return {
    value,
    previous: before,
    change,
    rows: current.map((point, index) => ({
      day: dayFormat.format(dayStart(start + index)),
      value: point,
    })),
  };
}

export function formatChange(metric: Metric, change: number) {
  const sign = change > 0 ? "+" : change < 0 ? "−" : "";
  const size = Math.abs(change).toFixed(metric.points ? 2 : 1);
  return `${sign}${size}${metric.points ? " pts" : "%"}`;
}

"use client";

import { areaY, defineChart, lineY } from "@tanstack/charts";
import { decorative } from "@tanstack/charts/mark/decorative";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import { scalePoint } from "@tanstack/charts/scales/point";
import { tooltip } from "@tanstack/charts/tooltip";
import { portal } from "@tanstack/charts/tooltip/portal";
import { useMemo, useState } from "react";
import { AnimatedNumber } from "../../vip-ui/animated-number";
import { Chart } from "../../vip-ui/chart";
import { Stat, StatDetail, StatLabel, StatTrend } from "../../vip-ui/stat";
import { ToggleButton } from "../../vip-ui/toggle-button";
import { ToggleButtonGroup } from "../../vip-ui/toggle-button-group";
import {
  formatChange,
  type Metric,
  metrics,
  type Period,
  periodLabels,
  readMetric,
} from "./data";

function Sparkline({
  metric,
  rows,
  good,
}: {
  metric: Metric;
  rows: { day: string; value: number }[];
  good: boolean;
}) {
  const color = good ? "var(--success)" : "var(--destructive)";
  const definition = useMemo(() => {
    const format = new Intl.NumberFormat("en-US", metric.format);
    const values = rows.map((row) => row.value);
    const min = Math.min(...values);
    const max = Math.max(...values);
    const pad = (max - min) * 0.15 || max * 0.05;
    return defineChart({
      guides: false,
      margin: { top: 6, right: 0, bottom: 0, left: 0 },
      keyboard: false,
      marks: [
        decorative(
          areaY(rows, {
            x: "day",
            y: "value",
            y1: min - pad,
            fill: color,
            fillOpacity: 0.12,
          }),
        ),
        lineY(rows, {
          x: "day",
          y: "value",
          stroke: color,
          strokeWidth: rows.length > 30 ? 1.5 : 2,
        }),
      ],
      scales: {
        x: { scale: scalePoint },
        y: { scale: scaleLinear().domain([min - pad, max + pad]) },
      },
      tooltip: {
        use: tooltip,
        portal,
        content: ([point]) => ({
          rows: [
            {
              label: point.datum.day,
              value: format.format(point.datum.value),
              color: point.color,
            },
          ],
        }),
      },
    });
  }, [rows, color, metric]);

  return (
    <Chart
      definition={definition}
      height={56}
      initialWidth={280}
      ariaLabel={`${metric.label} from ${rows[0].day} to ${rows[rows.length - 1].day}`}
    />
  );
}

function MetricCard({ metric, period }: { metric: Metric; period: Period }) {
  const reading = useMemo(() => readMetric(metric, period), [metric, period]);
  const direction =
    reading.change > 0 ? "up" : reading.change < 0 ? "down" : "neutral";
  const good = reading.change === 0 || reading.change > 0 !== metric.invert;
  const format = new Intl.NumberFormat("en-US", metric.format);

  return (
    <Stat className="grid gap-0 overflow-hidden p-0">
      <div className="px-4 pt-4">
        <StatLabel>{metric.label}</StatLabel>
        <p className="mt-1 flex flex-wrap items-baseline gap-x-2 gap-y-1">
          <AnimatedNumber
            value={reading.value}
            formatOptions={metric.format}
            className="text-3xl font-semibold tracking-[-0.045em] tabular-nums"
          />
          <StatTrend direction={direction} invert={metric.invert}>
            {formatChange(metric, reading.change)}
          </StatTrend>
        </p>
        <StatDetail className="tabular-nums">
          Previous {periodLabels[period]}: {format.format(reading.previous)}
        </StatDetail>
      </div>
      <div className="mt-3">
        <Sparkline metric={metric} rows={reading.rows} good={good} />
      </div>
    </Stat>
  );
}

export function StatsCards() {
  const [period, setPeriod] = useState<Period>("30d");

  return (
    <section aria-labelledby="stats-title" className="grid gap-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1
            id="stats-title"
            className="text-xl font-semibold tracking-[-0.035em]"
          >
            Business health
          </h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Last {periodLabels[period]} to September 30, compared with the
            previous {periodLabels[period]}
          </p>
        </div>
        <ToggleButtonGroup
          aria-label="Period"
          selectionMode="single"
          disallowEmptySelection
          selectedKeys={[period]}
          onSelectionChange={(keys) => {
            const [next] = keys;
            if (next) setPeriod(next as Period);
          }}
        >
          {(Object.keys(periodLabels) as Period[]).map((key) => (
            <ToggleButton key={key} id={key} variant="segmented">
              {periodLabels[key]}
            </ToggleButton>
          ))}
        </ToggleButtonGroup>
      </div>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {metrics.map((metric) => (
          <MetricCard key={metric.id} metric={metric} period={period} />
        ))}
      </div>
    </section>
  );
}

import { StatsCards } from "./stats-cards";

export function StatsPage() {
  return (
    <main className="flex min-h-svh items-center justify-center bg-background p-6 md:p-10">
      <div className="w-full max-w-6xl">
        <StatsCards />
      </div>
    </main>
  );
}
